    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '201: A breastfed infant requires Vitamin D supplementation. Why is this necessary despite breast milk being the ideal food?', '["Breast milk has a component that blocks Vitamin D absorption", "Breast milk contains insufficient Vitamin D (approx 22 IU/L) to prevent rickets", "Infants cannot synthesize Vitamin D from the sun", "Formula has less Vitamin D than breast milk"]', 1, 'Human milk is notoriously deficient in Vitamin D, necessitating the 400 IU/day supplementation.'),
    (v_topic_id, '202: A child presents with bowing of the legs and is diagnosed with Vitamin D deficiency rickets. What is the classic X-ray finding at the growth plate?', '["Thinning of the cortex", "Sclerosis of the metaphysis", "Widening, cupping, and fraying of the metaphysis", "Punched-out lytic lesions"]', 2, 'The osteoid matrix fails to calcify, leading to a disorganized, widened, and frayed appearance at the ends of long bones.'),
    (v_topic_id, '203: A 6-month-old infant is introduced to solid foods. The mother gives homemade spinach puree. What life-threatening condition can this cause?', '["Vitamin A toxicity", "Methemoglobinemia", "Botulism", "Scurvy"]', 1, 'Nitrates in root vegetables and spinach are converted to nitrites by gut bacteria, causing methemoglobinemia (chocolate-colored blood and cyanosis).'),
    (v_topic_id, '204: A child with cystic fibrosis is prone to fat malabsorption. Which symptom strongly suggests Vitamin E deficiency?', '["Night blindness", "Bleeding diathesis", "Ataxia and loss of proprioception", "Rickets"]', 2, 'Vitamin E deficiency mimics Friedreich ataxia or B12 deficiency (spinocerebellar degeneration).'),
    (v_topic_id, '205: A child has a severe allergy to cow''s milk protein. Which formula is most appropriate?', '["Soy formula", "Goat''s milk", "Extensively hydrolyzed (or amino acid-based) formula", "Low-lactose formula"]', 2, 'Up to 30% of infants with cow''s milk allergy cross-react to soy. Extensively hydrolyzed formulas break proteins into non-allergenic peptides.'),
    (v_topic_id, '206: A neonate presents with jitteriness and seizures on day 2 of life. The mother had poor prenatal care and a highly processed diet. Calcium is 6.5 mg/dL. The infant has a "rachitic rosary." What did the mother lack?', '["Vitamin C", "Vitamin D", "Iron", "Vitamin A"]', 1, 'Maternal Vitamin D deficiency leads to severe congenital rickets and neonatal hypocalcemia.'),
    (v_topic_id, '207: A 2-year-old child from a developing country has a distended abdomen, thin limbs, and severe edema. The diet consists mostly of cassava root (very low protein). Diagnosis?', '["Marasmus", "Kwashiorkor", "Celiac disease", "Biliary atresia"]', 1, 'Kwashiorkor is protein malnutrition with adequate total calories, leading to hypoalbuminemia and edema.'),
    (v_topic_id, '208: A child with severe Kwashiorkor is at highest risk of death from which complication during the initial presentation?', '["Heart failure", "Infection/Sepsis (due to severe immunosuppression)", "Renal failure", "Liver failure"]', 1, 'Severe protein malnutrition causes profound immunodeficiency (thymic atrophy, impaired cell-mediated immunity).'),
    (v_topic_id, '209: A child is diagnosed with Anorexia Nervosa. They have a BMI of 13. Which electrolyte abnormality is most dangerous during the first week of refeeding?', '["Hypercalcemia", "Hypophosphatemia", "Hyperkalemia", "Hypernatremia"]', 1, 'Hypophosphatemia is the hallmark of Refeeding Syndrome, leading to ATP depletion and fatal arrhythmias.'),
    (v_topic_id, '210: What is the classic dermatologic finding in a child with Pellagra (Vitamin B3 deficiency)?', '["A vesicular rash around the mouth", "A symmetric, hyperpigmented, scaling rash on sun-exposed areas (Casal necklace)", "Petechiae and purpura", "Eczema"]', 1, 'Pellagra dermatitis is photosensitive and sharply demarcated.'),
    (v_topic_id, '211: A child treated with Isoniazid for latent TB develops numbness and tingling in their hands and feet. What vitamin should have been co-administered?', '["Vitamin B1 (Thiamine)", "Vitamin B6 (Pyridoxine)", "Vitamin B12", "Folate"]', 1, 'INH depletes Pyridoxine, leading to peripheral neuropathy.'),
    (v_topic_id, '212: A premature infant develops hemolytic anemia and edema. They are being fed a formula high in polyunsaturated fats but lacking a specific antioxidant. Deficient vitamin?', '["Vitamin A", "Vitamin C", "Vitamin E", "Vitamin K"]', 2, 'Vitamin E protects RBC membranes from oxidative stress.'),
    (v_topic_id, '213: A child on a strict vegan diet for 5 years presents with macrocytic anemia and loss of vibratory sensation in the toes. Deficient nutrient?', '["Folate", "Iron", "Vitamin B12", "Zinc"]', 2, 'B12 deficiency causes subacute combined degeneration of the spinal cord.'),
    (v_topic_id, '214: A child with a history of recurrent intussusception is found to have a lead point. They also have chronic diarrhea and failure to thrive. A biopsy shows villous atrophy. Diagnosis?', '["Crohn''s disease", "Celiac disease", "Meckel diverticulum", "Cystic fibrosis"]', 1, 'Celiac disease can rarely present with intussusception due to altered bowel motility and thickened loops of bowel.'),
    (v_topic_id, '215: What is the most sensitive and specific initial serologic test for Celiac disease?', '["Anti-gliadin antibodies", "Anti-endomysial antibodies", "Tissue transglutaminase (tTG) IgA antibodies", "HLA-DQ2 testing"]', 2, 'tTG IgA is the preferred screening test, provided the patient does not have selective IgA deficiency.'),
    (v_topic_id, '216: If a patient has selective IgA deficiency, which test should be used to screen for Celiac disease?', '["tTG IgA", "tTG IgG or deamidated gliadin peptide (DGP) IgG", "Stool culture", "Sweat chloride test"]', 1, 'Since they lack IgA, an IgG-based test must be used.'),
    (v_topic_id, '217: A child presents with bleeding gums, poor wound healing, and petechiae. They refuse to eat any fruits or vegetables. Diagnosis?', '["Scurvy (Vitamin C deficiency)", "Rickets", "Beriberi", "Pellagra"]', 0, 'Vitamin C is required for collagen synthesis.'),
    (v_topic_id, '218: A child with severe iron deficiency anemia is found to have koilonychia. What does this look like?', '["Clubbed fingers", "Spoon-shaped, concave nails", "Splinter hemorrhages", "Pitting of the nails"]', 1, 'Koilonychia is a classic sign of chronic iron deficiency.'),
    (v_topic_id, '219: A child with a high lead level (lead poisoning) often has a concurrent deficiency in which mineral, which exacerbates lead absorption?', '["Calcium", "Iron", "Zinc", "Magnesium"]', 1, 'Iron deficiency upregulates intestinal transporters that also absorb lead.'),
    (v_topic_id, '220: A neonate with Cystic Fibrosis presents with a prolonged PT and PTT, but normal platelet count. They have a large cephalohematoma. Which vitamin is deficient?', '["Vitamin A", "Vitamin C", "Vitamin K", "Vitamin E"]', 2, 'Fat malabsorption in CF leads to Vitamin K deficiency and subsequent bleeding diathesis.'),
    (v_topic_id, '221: A child from a developing country presents with severe heart failure, peripheral edema, and a diet consisting entirely of polished white rice. Diagnosis?', '["Wet Beriberi (Thiamine deficiency)", "Dry Beriberi", "Scurvy", "Pellagra"]', 0, 'Wet beriberi causes high-output cardiac failure.'),
    (v_topic_id, '222: A child presents with angular stomatitis (fissures at the corners of the mouth), glossitis, and seborrheic dermatitis. Deficient vitamin?', '["Vitamin B1", "Vitamin B2 (Riboflavin)", "Vitamin B3", "Vitamin B6"]', 1, 'Riboflavin deficiency classically affects the mucocutaneous surfaces.'),
    (v_topic_id, '223: A patient with Anorexia Nervosa has a fine, downy hair covering their back and arms. What is this called?', '["Acanthosis nigricans", "Lanugo", "Hirsutism", "Hypertrichosis"]', 1, 'Lanugo grows as a physiologic response to conserve heat when body fat is severely depleted.'),
    (v_topic_id, '224: A patient with Bulimia Nervosa frequently vomits. What metabolic derangement is classic?', '["Hyperkalemic acidosis", "Hypokalemic, hypochloremic metabolic alkalosis", "Hypernatremia", "Hypocalcemia"]', 1, 'Loss of gastric HCl and potassium leads to this classic derangement.'),
    (v_topic_id, '225: A patient with Bulimia Nervosa has calluses on the dorsum of their hands. What is this sign called?', '["Chvostek sign", "Trousseau sign", "Russell sign", "Gottron papules"]', 2, 'Caused by repeated friction against the upper incisors during self-induced vomiting.'),
    (v_topic_id, '226: A child on total parenteral nutrition (TPN) develops a perioral and perianal vesicular rash, alopecia, and diarrhea. Deficient trace mineral?', '["Copper", "Zinc", "Selenium", "Chromium"]', 1, 'Acrodermatitis enteropathica is the classic presentation of zinc deficiency.'),
    (v_topic_id, '227: A child with short bowel syndrome on TPN develops a severe cardiomyopathy. Deficient trace mineral?', '["Copper", "Zinc", "Selenium", "Iron"]', 2, 'Selenium deficiency causes Keshan disease (congestive cardiomyopathy).'),
    (v_topic_id, '228: A child with a history of massive bowel resection presents with macrocytic anemia and neurologic symptoms. Which part of the bowel was most likely resected?', '["Duodenum", "Jejunum", "Terminal ileum", "Colon"]', 2, 'Vitamin B12 is absorbed exclusively in the terminal ileum.'),
    (v_topic_id, '229: A neonate has a meconium ileus. This is almost pathognomonic for which condition that causes severe malabsorption?', '["Celiac disease", "Cystic fibrosis", "Hirschsprung disease", "Biliary atresia"]', 1, 'The thick, inspissated meconium blocks the ileum due to lack of pancreatic enzymes and abnormal chloride channel function.'),
    (v_topic_id, '230: A child with Cystic Fibrosis requires pancreatic enzyme replacement therapy (PERT). The dose is titrated based on the intake of which macronutrient?', '["Carbohydrates", "Protein", "Fat", "Fiber"]', 2, 'PERT is dosed according to the fat content of the meal to prevent steatorrhea.'),
    (v_topic_id, '231: A 12-month-old child drinks 48 ounces of cow''s milk per day and refuses all solid foods. They appear pale and irritable. What is the most likely diagnosis?', '["Vitamin B12 deficiency", "Iron deficiency anemia", "Lead poisoning", "Scurvy"]', 1, 'Excessive cow''s milk intake (>24 oz/day) is the leading cause of iron deficiency anemia in toddlers.'),
    (v_topic_id, '232: A child presents with night blindness and dry, thickened conjunctivae with foamy, silvery spots (Bitot spots). Diagnosis?', '["Vitamin A deficiency", "Vitamin C deficiency", "Zinc deficiency", "Cataracts"]', 0, 'Classic signs of Vitamin A deficiency (xerophthalmia).'),
    (v_topic_id, '233: A child is brought to the clinic for "bowed legs" (genu varum). The child is 18 months old, otherwise healthy, growing well, and has normal calcium/phosphorus levels. Diagnosis?', '["Rickets", "Blount disease", "Physiologic genu varum", "Osteogenesis imperfecta"]', 2, 'Mild bowing is physiologic and normal up to age 2. It usually corrects itself as the child grows.'),
    (v_topic_id, '234: A 3-year-old child presents with "knock-knees" (genu valgum). They are healthy and growing well. Diagnosis?', '["Rickets", "Physiologic genu valgum", "Scurvy", "Blount disease"]', 1, 'After age 2, physiologic bowing often transitions to physiologic knock-knees, peaking around age 3-4.'),
    (v_topic_id, '235: A child has severe obesity (BMI > 99th percentile), hyperphagia, hypotonia, and cryptorchidism. Genetic testing shows a paternal deletion on chromosome 15. Diagnosis?', '["Angelman syndrome", "Prader-Willi syndrome", "Down syndrome", "Fragile X syndrome"]', 1, 'Prader-Willi syndrome is a classic genetic cause of extreme obesity due to uncontrollable appetite.'),
    (v_topic_id, '236: A child with obesity presents with a dark, velvety thickening of the skin on the back of the neck (acanthosis nigricans). What does this indicate?', '["Poor hygiene", "Fungal infection", "Insulin resistance", "Adrenal insufficiency"]', 2, 'Acanthosis nigricans is a cutaneous marker of hyperinsulinemia/insulin resistance.'),
    (v_topic_id, '237: A child with a severe cow''s milk protein allergy presents with anaphylaxis. What is the immediate drug of choice?', '["Diphenhydramine (Benadryl)", "Epinephrine IM", "Albuterol nebulizer", "Intravenous fluids"]', 1, 'Intramuscular epinephrine is the life-saving treatment of choice for any anaphylactic reaction.'),
    (v_topic_id, '238: A 4-month-old infant is exclusively breastfed. The mother asks if she should start giving the baby water because it is summer. Advice?', '["Yes, 4 oz per day", "No, breast milk provides adequate hydration. Extra water risks hyponatremia.", "Yes, but add sugar", "Yes, but add salt"]', 1, 'Infants under 6 months do not need extra free water. It can lead to water intoxication and seizures.'),
    (v_topic_id, '239: At what age does the AAP recommend introducing solid foods (complementary foods) to an infant?', '["2 months", "Around 4-6 months, when the infant shows signs of readiness (e.g., sitting up, loss of extrusion reflex)", "9 months", "12 months"]', 1, 'Introducing solids too early risks aspiration and allergies; too late risks nutritional deficiencies (especially iron).'),
    (v_topic_id, '240: An infant is diagnosed with classical Galactosemia (GALT deficiency). What must be immediately removed from the diet?', '["Fructose", "Sucrose", "Lactose (all dairy, including breast milk)", "Glucose"]', 2, 'Lactose is broken down into glucose and galactose. Therefore, all sources of lactose/galactose must be strictly avoided.'),
    (v_topic_id, '241: A child with Hereditary Fructose Intolerance (Aldolase B deficiency) develops severe hypoglycemia when they consume:', '["Milk", "Fruit juice (fructose/sucrose)", "Meat", "Eggs"]', 1, 'Fructose-1-phosphate accumulates and competitively inhibits glycogenolysis and gluconeogenesis.'),
    (v_topic_id, '242: A child with Von Gierke disease (Type I Glycogen Storage Disease) presents with lactic acidosis, hyperuricemia, and severe hypoglycemia. What enzyme is deficient?', '["Acid maltase", "Glucose-6-phosphatase", "Debranching enzyme", "Branching enzyme"]', 1, 'The liver cannot convert glucose-6-phosphate to glucose, trapping it inside the cell.'),
    (v_topic_id, '243: A neonate presents with failure to thrive, vomiting, and a musty (mousy) body odor. They have fair skin and blonde hair compared to their siblings. Diagnosis?', '["Galactosemia", "Phenylketonuria (PKU)", "Maple syrup urine disease", "Homocystinuria"]', 1, 'Accumulation of phenylalanine causes the musty odor, while lack of tyrosine limits melanin production.'),
    (v_topic_id, '244: What is the treatment for PKU?', '["A diet low in phenylalanine and supplemented with tyrosine", "A diet free of all protein", "High-dose Vitamin B12", "Liver transplant"]', 0, 'Phenylalanine is an essential amino acid, so it cannot be eliminated entirely, but it must be strictly limited. Tyrosine becomes essential.'),
    (v_topic_id, '245: A neonate''s diapers smell like maple syrup. They are lethargic and having seizures. Which branched-chain amino acids are accumulating?', '["Phenylalanine, Tyrosine", "Leucine, Isoleucine, Valine", "Lysine, Arginine", "Methionine, Cysteine"]', 1, 'Maple Syrup Urine Disease (MSUD) is a defect in branched-chain alpha-ketoacid dehydrogenase.'),
    (v_topic_id, '246: A 2-year-old child presents with chronic, foul-smelling diarrhea, failure to thrive, and a chronic cough. Sweat chloride test is positive. Diagnosis?', '["Celiac disease", "Cystic fibrosis", "Asthma", "Primary ciliary dyskinesia"]', 1, 'CF causes both pancreatic insufficiency (malabsorption) and thick pulmonary secretions (chronic lung infections).'),
    (v_topic_id, '247: What is the primary cause of Failure to Thrive in a child with a large Ventricular Septal Defect (VSD)?', '["Malabsorption", "Increased metabolic demand (due to heart failure and increased work of breathing)", "Vomiting", "Diarrhea"]', 1, 'Congenital heart disease causes organic FTT by drastically increasing the calories burned just to breathe and pump blood.'),
    (v_topic_id, '248: A 6-month-old infant with FTT has severe gastroesophageal reflux. They arch their back and cry during feeds. This behavior is known as:', '["Colic", "Sandifer syndrome", "Pica", "Rumination"]', 1, 'Sandifer syndrome is a reflex posturing (arching of the back/neck) to protect the airway from acidic reflux.'),
    (v_topic_id, '249: A child is admitted with "Psychosocial Failure to Thrive" (Non-organic FTT). What is the most expected finding during their hospital stay?', '["They fail to gain weight despite adequate calories", "They gain weight rapidly when provided with adequate calories and a nurturing environment", "They require a feeding tube", "They have chronic diarrhea"]', 1, 'Rapid weight gain in the hospital (away from the stressful home environment and with guaranteed calories) confirms the diagnosis.'),
    (v_topic_id, '250: A toddler presents with "Toddler''s Diarrhea" (Chronic nonspecific diarrhea). They have 4-6 loose stools a day with undigested food, but their growth (weight/height) is perfectly normal. What is the best management?', '["Extensive workup for Celiac disease", "Reassure parents, reduce fruit juice intake, and increase dietary fat", "Start antibiotics", "Start loperamide"]', 1, 'This is a benign condition often caused by excess sorbitol/fructose from juice and low dietary fat.'),
    (v_topic_id, '251: A child with Autism Spectrum Disorder will only eat chicken nuggets and french fries. They are at risk for which nutritional deficiency if they refuse all fruits/vegetables?', '["Vitamin C (Scurvy)", "Protein", "Fat", "Sodium"]', 0, 'Highly restricted "beige" diets often lack Vitamin C, leading to modern-day scurvy.'),
    (v_topic_id, '252: A child presents with Menkes kinky hair syndrome (sparse, brittle hair, neurodegeneration). Which trace mineral absorption is defective?', '["Zinc", "Copper", "Iron", "Selenium"]', 1, 'Copper is trapped in the enterocytes and cannot reach the systemic circulation.'),
    (v_topic_id, '253: A child from an impoverished area has a large goiter and intellectual disability. Deficient nutrient?', '["Iodine", "Iron", "Vitamin A", "Zinc"]', 0, 'Endemic cretinism due to severe maternal iodine deficiency.'),
    (v_topic_id, '254: Which vitamin enhances the absorption of non-heme iron from plant sources?', '["Vitamin D", "Vitamin C", "Vitamin B12", "Vitamin A"]', 1, 'Vitamin C keeps iron in the ferrous (Fe2+) state.'),
    (v_topic_id, '255: A child has a genetic defect preventing the synthesis of intrinsic factor. They will develop:', '["Pernicious anemia (Vitamin B12 deficiency)", "Iron deficiency anemia", "Scurvy", "Rickets"]', 0, 'Intrinsic factor, secreted by gastric parietal cells, is essential for B12 absorption in the terminal ileum.'),
    (v_topic_id, '256: A child presents with obesity, short stature, and a round "moon" face. They have purple striae on their abdomen. Diagnosis?', '["Prader-Willi syndrome", "Cushing syndrome (excess cortisol)", "Hypothyroidism", "Simple obesity"]', 1, 'Excess cortisol causes central obesity, poor linear growth, and skin thinning (striae).'),
    (v_topic_id, '257: How does the growth pattern of a child with simple (nutritional) obesity differ from a child with an endocrine cause of obesity (like Cushing''s or Hypothyroidism)?', '["Simple obesity is associated with normal or tall stature, while endocrine causes present with short stature and poor linear growth", "Simple obesity causes short stature", "They are identical", "Endocrine obesity causes tall stature"]', 0, 'Children with simple obesity often have advanced bone age and are taller than their peers. Endocrine obesity stunts linear growth.'),
    (v_topic_id, '258: A child with obesity develops a severe headache, blurry vision, and papilledema. MRI of the brain is normal. Diagnosis?', '["Brain tumor", "Idiopathic Intracranial Hypertension (Pseudotumor cerebri)", "Migraine", "Meningitis"]', 1, 'Pseudotumor cerebri is strongly associated with obesity, especially in adolescent females.'),
    (v_topic_id, '259: What is the treatment for Idiopathic Intracranial Hypertension (Pseudotumor cerebri)?', '["Weight loss and Acetazolamide", "Chemotherapy", "Antibiotics", "Corticosteroids"]', 0, 'Acetazolamide decreases CSF production, and weight loss is curative in many cases.'),
    (v_topic_id, '260: A patient with Anorexia Nervosa has a core body temperature of 35.0°C (95°F). Why does this happen?', '["Infection", "Physiologic adaptation to starvation (decreased metabolic rate to conserve energy)", "Hyperthyroidism", "Fever"]', 1, 'Hypothermia, bradycardia, and hypotension are all signs that the body is shutting down non-essential functions to survive starvation.'),
    (v_topic_id, '261: A child with Anorexia Nervosa is admitted. Their phosphorus drops from 3.5 to 1.0 mg/dL on the second day of meals. What must be done?', '["Increase feeding rate", "Decrease or pause caloric intake, supplement phosphorus IV or orally, and monitor closely", "Do nothing, this is normal", "Give insulin"]', 1, 'Refeeding syndrome requires immediate intervention to correct electrolytes before resuming feeds slowly.'),
    (v_topic_id, '262: A child has a severe allergy to eggs. They need a flu vaccine. What is the current CDC recommendation?', '["They cannot receive the flu vaccine", "They can receive any age-appropriate flu vaccine without special precautions beyond standard anaphylaxis readiness", "They must be hospitalized to receive it", "They can only receive the recombinant vaccine"]', 1, 'The amount of egg protein in modern flu vaccines is negligible, and they are safe for egg-allergic patients.'),
    (v_topic_id, '263: A 6-month-old infant presents with a "beefy red" tongue, megaloblastic anemia, and developmental delay. The mother is a strict vegetarian. Which vitamin is she likely deficient in, causing the infant''s symptoms?', '["Iron", "Folate", "Vitamin B12", "Vitamin C"]', 2, 'Maternal B12 deficiency leads to low levels in breast milk.'),
    (v_topic_id, '264: A child with short bowel syndrome on TPN develops severe cholestasis and direct hyperbilirubinemia. What is the long-term solution?', '["Increase TPN lipids", "Liver/Intestine transplant if enteral autonomy cannot be achieved", "Increase TPN dextrose", "Start antibiotics"]', 1, 'Irreversible TPN-associated liver disease is a major indication for multi-visceral transplant.'),
    (v_topic_id, '265: A child has chronic pancreatitis and fat malabsorption. They are given medium-chain triglycerides (MCTs) as a supplement. Why?', '["They taste better", "They are absorbed directly into the portal vein and do not require pancreatic lipase or bile salts", "They contain more calories than long-chain fats", "They prevent diabetes"]', 1, 'MCTs are a direct energy source that bypasses the complex digestion required for standard fats.'),
    (v_topic_id, '266: A neonate presents with a distended abdomen and failure to pass meconium. A rectal suction biopsy shows an absence of ganglion cells. Diagnosis?', '["Meconium ileus", "Hirschsprung disease", "Intussusception", "Volvulus"]', 1, 'The aganglionic segment remains tonically contracted, causing a functional obstruction.'),
    (v_topic_id, '267: A child with Hirschsprung disease is at risk for which life-threatening complication if the bowel becomes inflamed and distended?', '["Appendicitis", "Hirschsprung-associated enterocolitis (HAEC)", "Celiac crisis", "Pyloric stenosis"]', 1, 'HAEC presents with explosive, foul-smelling diarrhea, fever, and lethargy. It can rapidly progress to sepsis and toxic megacolon.'),
    (v_topic_id, '268: A child presents with "Failure to Thrive." The growth chart shows that the child''s weight and height have always been at the 3rd percentile, parallel to the normal curve. The parents are both very short. Bone age is equal to chronological age. Diagnosis?', '["Constitutional growth delay", "Familial short stature", "Hypothyroidism", "Growth hormone deficiency"]', 1, 'In familial short stature, bone age is normal, and growth is parallel to the curve (just at the lower end).'),
    (v_topic_id, '269: A child presents with short stature. The growth curve shows a deceleration in height, but weight is maintained or increasing. Bone age is delayed. Diagnosis?', '["Familial short stature", "Endocrine cause (e.g., Growth hormone deficiency or Hypothyroidism)", "Malnutrition", "Turner syndrome"]', 1, 'Endocrine causes typically stunt linear growth while sparing (or increasing) weight. Bone age is usually delayed.'),
    (v_topic_id, '270: A child with "Failure to Thrive" shows weight dropping across percentiles, followed later by a drop in height. Bone age is delayed. Diagnosis?', '["Endocrine cause", "Nutritional/Systemic illness (Malnutrition)", "Familial short stature", "Constitutional growth delay"]', 1, 'In malnutrition, weight is affected first, then height. Bone age is delayed due to poor nutrition.'),
    (v_topic_id, '271: A teenager presents with short stature but a normal growth velocity. Their parents are of average height but state they were "late bloomers." Bone age is significantly delayed. What is the expected outcome?', '["They will remain short adults", "They have Constitutional Growth Delay and will eventually catch up to a normal adult height", "They require growth hormone therapy", "They have Turner syndrome"]', 1, 'Constitutional growth delay ("late bloomers") have delayed puberty and bone age, but eventually reach a normal final adult height.'),
    (v_topic_id, '272: A 3-week-old male infant presents with non-bilious, projectile vomiting. He has an "olive-like" mass in the right upper quadrant. Diagnosis?', '["Pyloric stenosis", "Duodenal atresia", "Midgut volvulus", "Intussusception"]', 0, 'Hypertrophic pyloric stenosis causes gastric outlet obstruction.'),
    (v_topic_id, '273: What classic acid-base abnormality is seen in Pyloric Stenosis?', '["Hyperchloremic metabolic acidosis", "Hypochloremic, hypokalemic metabolic alkalosis", "Respiratory acidosis", "Respiratory alkalosis"]', 1, 'Vomiting of gastric HCl leads to alkalosis and loss of chloride. The kidneys trade potassium to save protons, worsening hypokalemia.'),
    (v_topic_id, '274: A 1-year-old child has a sudden onset of colicky abdominal pain. They draw their legs up to their chest and cry inconsolably. Between episodes, they act completely normal. Later, they pass "currant-jelly" stool. Diagnosis?', '["Appendicitis", "Intussusception", "Volvulus", "Gastroenteritis"]', 1, 'Intussusception (telescoping of the bowel) causes intermittent ischemia and pain. Currant-jelly stool is a late sign of mucosal necrosis.'),
    (v_topic_id, '275: What is the initial diagnostic and often therapeutic modality for pediatric Intussusception?', '["CT scan of the abdomen", "Air or contrast enema", "Upper GI series", "Exploratory laparotomy"]', 1, 'Ultrasound is used for diagnosis (target sign), but a pneumatic (air) or hydrostatic enema is both diagnostic and curative in most cases.'),
    (v_topic_id, '276: A neonate presents with bilious vomiting on day 2 of life. Abdominal X-ray shows a "double bubble" sign. Diagnosis?', '["Pyloric stenosis", "Duodenal atresia", "Hirschsprung disease", "Necrotizing enterocolitis"]', 1, 'Duodenal atresia is strongly associated with Down syndrome. The bubbles are the dilated stomach and proximal duodenum.'),
    (v_topic_id, '277: A 1-month-old infant presents with sudden onset of severe bilious vomiting and a rigid abdomen. Upper GI series shows a "corkscrew" appearance of the duodenum and the ligament of Treitz is on the right side. Diagnosis?', '["Malrotation with midgut volvulus", "Pyloric stenosis", "Intussusception", "Duodenal atresia"]', 0, 'Midgut volvulus is a surgical emergency. The bowel twists on its mesenteric axis, rapidly causing ischemic necrosis of the entire midgut.'),
    (v_topic_id, '278: A premature infant (28 weeks gestation) develops feeding intolerance, a distended abdomen, and bloody stools. X-ray shows pneumatosis intestinalis (air in the bowel wall). Diagnosis?', '["Intussusception", "Necrotizing enterocolitis (NEC)", "Hirschsprung disease", "Volvulus"]', 1, 'NEC is a devastating disease of premature infants involving ischemic necrosis of the bowel mucosa.'),
    (v_topic_id, '279: What is a major protective factor against Necrotizing Enterocolitis in premature infants?', '["Early formula feeding", "Exclusive human milk (breast milk) feeding", "Intravenous antibiotics", "High-dose Vitamin C"]', 1, 'Breast milk contains protective factors (IgA, lactoferrin) that significantly reduce the incidence of NEC compared to formula.'),
    (v_topic_id, '280: A 2-year-old child presents with painless, massive lower GI bleeding (maroon/brick-red stool). A technetium-99m pertechnetate scan is positive in the right lower quadrant. Diagnosis?', '["Appendicitis", "Meckel diverticulum", "Intussusception", "Ulcerative colitis"]', 1, 'Meckel diverticulum often contains ectopic gastric mucosa, which secretes acid and ulcerates the adjacent ileum, causing painless bleeding. The scan detects gastric mucosa.'),
    (v_topic_id, '281: Which rule is associated with Meckel diverticulum?', '["Rule of 3s", "Rule of 2s (2% of population, 2 inches long, 2 feet from ileocecal valve, 2 types of ectopic tissue, presents by age 2)", "Rule of 9s", "Rule of 4s"]', 1, 'The Rule of 2s is the classic mnemonic for Meckel diverticulum.'),
    (v_topic_id, '282: A child is diagnosed with Celiac disease. In addition to wheat, barley, and rye, which other grain must occasionally be avoided due to cross-contamination or cross-reactivity?', '["Rice", "Corn", "Oats", "Quinoa"]', 2, 'While pure oats are safe, they are often contaminated with wheat during processing. Some patients also react to avenin in oats.'),
    (v_topic_id, '283: A child with untreated Celiac disease presents with a very itchy, blistering rash on their elbows and knees. Diagnosis?', '["Eczema", "Dermatitis herpetiformis", "Psoriasis", "Scabies"]', 1, 'Dermatitis herpetiformis is the cutaneous manifestation of Celiac disease, caused by IgA deposition in the dermal papillae.'),
    (v_topic_id, '284: What is the treatment for Dermatitis Herpetiformis?', '["Topical steroids", "Strict gluten-free diet and Dapsone", "Antifungals", "Antibiotics"]', 1, 'Dapsone provides rapid relief of the rash, but a strict gluten-free diet is required for long-term resolution.'),
    (v_topic_id, '285: A child has chronic constipation. They pass large, hard stools that clog the toilet and experience fecal incontinence (encopresis). Rectal exam shows a dilated vault full of stool. Diagnosis?', '["Hirschsprung disease", "Functional constipation with encopresis", "Spina bifida", "Cystic fibrosis"]', 1, 'In functional constipation, the rectum dilates and loses sensation. Liquid stool leaks around the hard impaction (encopresis).'),
    (v_topic_id, '286: What is the first step in the management of severe functional constipation with encopresis?', '["Surgical resection", "Fecal disimpaction (using oral PEG cleanout or enemas) before starting daily maintenance laxatives", "Increase dietary fiber alone", "Biofeedback"]', 1, 'You cannot treat constipation if there is a massive impaction blocking the exit. Disimpaction is mandatory first.'),
    (v_topic_id, '287: A 10-year-old child presents with chronic abdominal pain, weight loss, and diarrhea. They have aphthous ulcers in their mouth and a perianal skin tag. Diagnosis?', '["Ulcerative colitis", "Crohn''s disease", "Celiac disease", "IBS"]', 1, 'Crohn''s disease can affect any part of the GI tract (mouth to anus) and frequently causes perianal disease (tags, fistulas, abscesses).'),
    (v_topic_id, '288: Which inflammatory bowel disease is characterized by continuous mucosal inflammation starting at the rectum and extending proximally, without skip lesions?', '["Crohn''s disease", "Ulcerative colitis", "Celiac disease", "Microscopic colitis"]', 1, 'Ulcerative colitis is limited to the colon and rectum, and the inflammation is superficial (mucosal/submucosal).'),
    (v_topic_id, '289: A child with Ulcerative Colitis is at high long-term risk for developing which cancer?', '["Hepatocellular carcinoma", "Colorectal cancer", "Gastric cancer", "Pancreatic cancer"]', 1, 'The risk correlates with the duration and extent of colonic inflammation. Annual screening colonoscopies are required after 8-10 years of disease.'),
    (v_topic_id, '290: A 5-year-old child presents with jaundice, right upper quadrant pain, and a palpable abdominal mass. Ultrasound shows a cystic dilation of the common bile duct. Diagnosis?', '["Biliary atresia", "Choledochal cyst", "Hepatitis A", "Gallstones"]', 1, 'Choledochal cysts (congenital dilations of the biliary tree) present with this classic triad. They must be resected due to the risk of cholangiocarcinoma.'),
    (v_topic_id, '291: A neonate presents with progressive jaundice starting at 2 weeks of life, acholic (pale) stools, and dark urine. Ultrasound shows an "absent gallbladder" and a "triangular cord sign." Diagnosis?', '["Breast milk jaundice", "Biliary atresia", "Neonatal hepatitis", "Choledochal cyst"]', 1, 'Biliary atresia is an obliteration of the extrahepatic biliary tree. It requires urgent surgical intervention (Kasai procedure).'),
    (v_topic_id, '292: What is the procedure used to treat Biliary Atresia before liver transplant becomes necessary?', '["Whipple procedure", "Kasai portoenterostomy", "Cholecystectomy", "Nissen fundoplication"]', 1, 'The Kasai procedure connects a loop of jejunum directly to the porta hepatis to allow bile drainage. It is most effective if done before 8 weeks of life.'),
    (v_topic_id, '293: A child with severe liver failure and hepatic encephalopathy has an elevated ammonia level. Which medication is used to trap ammonia in the gut and excrete it?', '["Omeprazole", "Lactulose", "Ursodiol", "Cholestyramine"]', 1, 'Lactulose is fermented into lactic acid in the colon, which acidifies the gut. This traps NH3 as NH4+, which cannot be absorbed and is excreted.'),
    (v_topic_id, '294: A child with cystic fibrosis is prescribed Ursodiol. What is the purpose of this medication?', '["To treat pulmonary infections", "To replace pancreatic enzymes", "To promote bile flow and prevent/treat focal biliary cirrhosis", "To cure the CFTR defect"]', 2, 'Ursodiol is a hydrophilic bile acid that improves bile flow and protects hepatocytes from toxic hydrophobic bile acids.'),
    (v_topic_id, '295: A teenager presents with binge eating followed by intense feelings of guilt, but they DO NOT engage in compensatory behaviors (purging, extreme exercise). Their BMI is 35. Diagnosis?', '["Bulimia nervosa", "Binge-eating disorder", "Anorexia nervosa", "Prader-Willi syndrome"]', 1, 'Binge-eating disorder is characterized by frequent binges without the purging seen in Bulimia.'),
    (v_topic_id, '296: A child presents with vomiting, lethargy, and hepatomegaly a few days after recovering from a viral illness (influenza). The mother admits to giving the child aspirin for a fever. Diagnosis?', '["Hepatitis A", "Reye syndrome", "Acetaminophen toxicity", "Biliary atresia"]', 1, 'Aspirin use during a viral illness in children can trigger Reye syndrome (microvesicular fatty change in the liver and toxic encephalopathy).'),
    (v_topic_id, '297: A child accidentally ingests a bottle of acetaminophen. Which toxic metabolite is responsible for the massive hepatic necrosis?', '["NAPQI", "Salicylic acid", "Ammonia", "Formaldehyde"]', 0, 'NAPQI overwhelms the liver''s glutathione stores and causes centrilobular necrosis.'),
    (v_topic_id, '298: What is the antidote for Acetaminophen poisoning?', '["N-acetylcysteine (NAC)", "Naloxone", "Flumazenil", "Atropine"]', 0, 'NAC replenishes glutathione, allowing the liver to safely detoxify NAPQI.'),
    (v_topic_id, '299: A child swallows a button battery. X-ray shows it is lodged in the esophagus. What is the immediate next step?', '["Observe for 24 hours to see if it passes", "Endoscopic removal immediately", "Give Ipecac to induce vomiting", "Give a laxative"]', 1, 'A button battery in the esophagus is an absolute emergency. It generates an electrical current that causes severe liquefactive necrosis and perforation within hours.'),
    (v_topic_id, '300: Final Pearl: When counseling parents on infant nutrition, what is the single most important rule regarding the preparation of infant formula?', '["Always add sugar", "Always mix it with milk instead of water", "Always follow the manufacturer''s exact mixing instructions to avoid hyper/hyponatremic dehydration", "Always boil the formula for 10 minutes"]', 2, 'Improperly mixed formula (too dilute or too concentrated) is a leading cause of preventable, life-threatening electrolyte derangements in infants.');
